 "content": "def transform(grid):
    """Extend outward diagonal rays from 2x2 non-background motifs.

    A ray is extended only when the cell immediately beyond a motif corner
    already repeats that corner's color. Background cells along that outward
    diagonal are then filled with the color; existing foreground cells remain.
    """
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return out

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    corners_and_directions = (
        (-1, -1),  # top-left: continue northwest
        (-1, 1),   # top-right: continue northeast
        (1, -1),   # bottom-left: continue southwest
        (1, 1),    # bottom-right: continue southeast
    )
    for r in range(h - 1):
        for c in range(w - 1):
            corners = ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))
            if any(grid[rr][cc] == background for rr, cc in corners):
                continue
            for (rr, cc), (dr, dc) in zip(corners, corners_and_directions):
                color = grid[rr][cc]
                row, col = rr + dr, cc + dc
                # Require an immediately adjacent, same-color continuation mark.
                if not (0 <= row < h and 0 <= col < w and grid[row][col] == color):
                    continue
                while 0 <= row < h and 0 <= col < w:
                    if grid[row][col] == background:
                        out[row][col] = color
                    row += dr
                    col += dc
    return out
